import React, { useEffect }  from 'react';
import { useLocation } from 'react-router-dom';
function Host() {
     const location=useLocation()
     
      useEffect(() => {
        if(location.pathname!=="/host")return;
        const starsContainer = document.getElementById("stars");
    
       if(!starsContainer) return;
        starsContainer.innerHTML = "";
    
        for (let i = 0; i < 180; i++) {
          const star = document.createElement("div");
    
          const size =
            Math.random() > 0.96
              ? "lg"
              : Math.random() > 0.7
                ? "md"
                : "sm";
    
          star.className = `star ${size}`;
    
          star.style.left = Math.random() * 100 + "%";
          star.style.top = Math.random() * 100 + "%";
    
          star.style.animationDuration =
            2 + Math.random() * 6 + "s";
    
          star.style.animationDelay =
            Math.random() * 5 + "s";
    
          starsContainer.appendChild(star);
        }
      }, [location.pathname]);
      
  return (
    <>
      <div className="stars" id="stars"></div>
      <div className="container p-5 m-5">
         <button
      class="btn back-btn d-flex align-items-center gap-2 border border-2 rounded-pill"
    >
      <span
        ><i class="bi bi-arrow-left-short text-white fs-5 fw-bolder"></i
      ></span>
      <span class="text-white"> Go Back</span>
    </button>
      </div>
      </>
  )
}
export default Host;
